# Seed-estimation variant definitions, sourced by variants.sh and cyclevar.sh
# attrs: a dict for all tools, or a list of dicts, one per tool (pixel, strip)
tpe() {
  case "$1" in
    \[*) echo "[setattr(t, k, v) for t, a in zip(cfg.getEventAlgo('ActsTrackFindingAlg').TrackParamsEstimationTool, $1) for k, v in a.items()];";;
    *)   echo "[setattr(t, k, v) for t in cfg.getEventAlgo('ActsTrackFindingAlg').TrackParamsEstimationTool for k, v in $1.items()];";;
  esac
}
cfgof() {   # name -> "force|tool-attrs"
  case $1 in
    on)            echo "True|{}";;
    off)           echo "False|{}";;
    off-first3)    echo "False|{'parameterEstimationMode': 0}";;
    off-f3longp)   echo "False|{'parameterEstimationMode': 1}";;
    off-mindr)     echo "False|{'parameterEstimationMode': 3}";;
