    off-all-w1)    echo "False|{'parameterEstimationMode': 4, 'spacePointWeightExponent': 1.0}";;
    off-all-w2)    echo "False|{'parameterEstimationMode': 4, 'spacePointWeightExponent': 2.0}";;
